INSERT INTO `experiences` (`id`, `cv_id`, `periode`, `poste_exp`, `entreprise`, `description`, `outils`) VALUES
(821, 265, 'Depuis Mai 2024', 'Consultant Senior en gestion de projets et de programmes', 'Entreprise de service IT (Rabat, Maroc)', 'Consultant Senior en gestion de projets et de programmes :\r\n\r\n- Accompagnement d\'entreprises et établissements publiques sur les différents volets de la Transformation Digitale : Définition de la stratégie SI et élaboration d\'un SDSI, Urbanisation et Architecture SI, Refonte SI avec acquisition et mise en place d\'ERP, rédaction des cahiers de charge, Pilotage de projets en mode AGILE, élaboration du manuel de procédures et modélisation suivant les normes BPMN, des procédures, conduite de changement, création d\'applications mobiles...).\r\n\r\nGroupe Barid Al Maghrib (GBAM):\r\n- Analyse et mise en place d\'un tableau de bord relatif à l\'avancement du projet de mise en place d\'un ERP de gestion de l\'activité transport et logistique du groupe.\r\n- Analyse et réajustement de la méthodologie projet suivant les principes Agile.\r\n- Mise en place et exécution des stratégies de recette et de conduite de changement.\r\n\r\nAutorité Marocaine des Marchés des Capitaux (AMMC) :\r\n- Accompagnement de l\'Autorité Marocaine du marché des capitaux dans la réalisation des projets d\'architecture et d\'urbanisation de son Système d\'Information.\r\n\r\nAgence Nationale des Ports (ANP) :\r\n- Mise en place d\'un benchmark des ERP financiers.\r\n- Animation des ateliers et élaboration du cahier des charges pour l\'acquisition d\'un ERP Financier.', 'ERP, BPMN, Agile'),
(822, 265, 'Mai 2018 - Mai 2024', 'Chargé de mission auprès de la Direction Générale', 'Institution de Microfinance (Rabat, Maroc)', 'PMO en charge du pilotage et suivi du portefeuille de projet de la DSI :\r\n- Structuration de la méthodologie de suivi des projets au sein de la DSI.\r\n- Mise en place des documents de référence pour le suivi et la clôture des projets.\r\n- Mise en place des KPI et Tableau de bord permettant le pilotage et le suivi par la Direction Générale et la DSI.\r\n- Mise en place d\'un plan d\'Audit SI en collaboration avec le département d\'Audit Interne.\r\n\r\nProduct Owner projet de refonte du Core Banking System de l\'Institution :\r\n- Cadrage et expression de besoin, CRM, CORE, Cash Management, Application Mobile, Portail Web, mise en place et interfaçage avec l\'ERP Comptable, coordination avec les équipes SI pour la migration de données, mise en place de la stratégie de conduite de changement avec le plan de formation et le guide utilisateur, Stratégie de communication...).\r\n- Mise à jour des manuels de procédures et modélisation suivant les normes BPMN.\r\n\r\nBusiness Analyste / PMO en charge du pilotage et du suivi du projet de création et de mise en place de l\'ERP d\'un Etablissement De Paiement :\r\n- Mise en place de l\'application Mobile avec accès pour les comptes personnels et professionnels, définition des workflow transactionnel, mise en place et optimisation du processus de gestion des incidents, Optimisation des processus de gestion des demandes clients...).\r\n- Lancement et développement de l\'activité d\'Agent principal (Création d\'un Portail Web, Interfaçage avec le Core Banking System, mise en place de rapport sur le BI, conduite de changement avec la mise en place de guide utilisateur et l\'animation d\'atelier de formation, mise en place d\'un plan de communication...).\r\n- Pilotage et suivi de la mise en place du service de transfert d\'argent à l\'international en partenariat avec Western Union (mise en place de l\'outil fournit par Western Union, pilotage de la mise en place des développements spécifiques liés à la gestion de la caisse et des exercices de rapprochements avec les états bancaires, mise en place de la stratégie marketing, coordination avec la Direction des Affaires Générale pour la mise en place des installations au niveau des agences).\r\n- Pilotage et suivi de la mise en place du service de distribution des indemnités CNSS.\r\n- Mise à jour des manuels de procédures et modélisation suivant les normes BPMN.\r\n\r\nBusiness Analyste / PMO en charge de la revue et de l\'optimisation de l\'ERP gérant les activités de l\'institution :\r\n- Analyse de la cohérence entre les besoins métier et les fonctionnalités mise en place au niveau de l\'ERP.\r\n- Suivi de la mise en place d\'un progiciel de gestion des activités de recouvrement.\r\n- Mise en place d\'un plan d\'Audit SI en collaboration avec le département d\'Audit Interne.\r\n- Réalisation d\'une mission d\'Audit des Achats avec le département d\'Audit et la Direction des Affaires Générales en vue de l\'acquisition d\'un nouvel ERP pour la digitalisation des processus d\'achats.\r\n- Mise à jour des manuels de procédures et modélisation suivant les normes BPMN.', 'CRM, ERP, BPMN, Core Banking System, BI, Western Union'),
(823, 265, 'Mai 2017 - Mai 2018', 'Audit et Conseil des Systèmes d\'Information', 'Ernst Young (Casablanca, Maroc)', 'Conseil en stratégie SI:\r\n- Réalisation du diagnostic stratégique IT :\r\n  - Revue et analyse détaillée de l\'existant auprès des différentes lignes métiers.\r\n  - Animation d\'entretiens avec les différentes parties prenantes (AMOA, responsables métiers, MOE, prestataires)\r\n  - Etude de l\'alignement de la stratégie SI actuelle sur la stratégie globale de l\'entreprise à court et à long terme.\r\nAudit IT :\r\n- Audit informatique dans le cadre du CAC et prestations d\'Audit Interne :\r\n  - Diagnostic des systèmes d\'informations de plusieurs grands comptes au Maroc et réalisation des contrôles relatifs.', 'AMOA, MOE'),
(824, 265, 'Janvier - Juillet 2016', 'Assistant chef de projets en Transformation Digitale', 'Société Générale (Paris La Défense, France)', 'Pilotage et suivi, en mode agile, de projets de Transformation de la Direction des Risques du groupe Société Générale :\r\n- Mise en place et accompagnement, en collaboration avec les directeurs des départements Risque et les équipes IT, des projets de Transformation Digitale.\r\n- Animation d\'ateliers entre les métiers et l\'IT : identification du besoin, scoping, chiffrage et formalisation de livrables (docx, xlsx, pptx).\r\n- Création et animation de communautés collaboratives sur le réseau social interne de l\'entreprise pour la gestion de ces différents projets.', 'docx, xlsx, pptx, Agile'),
(825, 265, 'Novembre 2014 - Avril 2015', 'Analyste marché international', 'Orange Business Services (Saint-Denis, France)', 'Analyse du potentiel international des grands comptes d\'OBS :\r\n- Constitution de bases de données de prospection internationale structurées par zone géographique, par chiffre d\'affaires et par filiale permettant aux managers de comptes d\'identifier les potentiels de développement (sur la base des informations disponible sur les sites webs, les rapports annuels et l\'outil OneSource).\r\n- Elaboration et Mise en place avec les managers de comptes des différents plans d\'actions.', 'OneSource'),
(826, 265, 'Depuis 2013', 'Coaching scolaire et universitaire', '', 'Enseignement et accompagnement étudiants en difficulté :\r\n- Identification des difficultés rencontrées par les étudiants.\r\n- Simplification des notions de cours pour les aider à exprimer leurs idées tout en ayant une démarche scientifique.\r\n- Préparation de cours, d\'exercices et de cas pratiques adaptés pour les amener à identifier leurs propres difficultés et les aider à s\'améliorer.', ''),
(832, 267, '11 November 2025 - Aujourd\'hui', 'Senior Business Analyst Finance', 'DXC - CDG (Volkswagen Group)', 'Pilotage et coordination transverse des équipes Métiers, IT et intégrateurs dans des programmes de transformation SAP complexes (Groupe VW), avec gestion des dépendances et des priorités projet.\r\nCadrage fonctionnel et conception des solutions SAP FI/CO : analyse des besoins métiers, définition des processus cibles et contribution aux choix fonctionnels.\r\nSupervision des phases de recette SAP (UAT) : définition de la stratégie de test, validation des scénarios critiques et arbitrage des anomalies\r\nValidation et gouvernance des paramétrages SAP Finance : sécurisation des règles de gestion, contrôle de la conformité (finance, fiscalité) et optimisation des processus.\r\nAssistance à Maîtrise d\'Ouvrage (AMOA) : recueil et analyse des besoins, cadrage fonctionnel, accompagnement des métiers dans la définition des solutions et support à la prise de décision.\r\nAnimation des formations utilisateurs (End Users) : conception et animation de sessions de formation, accompagnement au changement et rédaction des supports pédagogiques.', 'SAP, SAP FI, SAP CO, UAT'),
(833, 267, '26 Janvier 2024 - 15 September 2025', 'Business Analyst Finance / AMOA', 'ALTEN (STELLANTIS)', 'Modélisation et optimisation des processus financiers (reporting, budgétisation, consolidation) afin d\'améliorer la fiabilité et la performance du pilotage financier.\r\nConception et déploiement de tableaux de bord interactifs (Power BI, Excel avancé) pour le suivi des indicateurs de performance et la prise de décision stratégique.\r\nAutomatisation des processus financiers et réduction des délais de clôture/reporting via l\'intégration d\'outils digitaux (Power BI, SAP BO).\r\nRédaction de la documentation fonctionnelle : cahiers des charges, spécifications détaillées et référentiels métiers.\r\nPilotage opérationnel des projets AMOA, en lien étroit avec les directions Finance et Contrôle de gestion, de la conception à la mise en production.\r\nSupervision des tests utilisateurs (UAT) : élaboration des scénarios, exécution des tests, suivi des anomalies et validation des livrables.\r\nFormation et accompagnement des utilisateurs finaux pour favoriser l\'appropriation des nouveaux outils et garantir une adoption réussie des solutions déployées.', 'Power BI, Excel, SAP BO, UAT'),
(834, 267, '07 Août 2023 - 25 Janvier 2024', 'Business Solutions Analyst', 'DISLOG GROUP', 'Accompagner les prestataires dans le paramétrage des comptes et règles de gestion.\r\nAccompagner les nouvelles sociétés dans la migration des données et paramétrage du SI.\r\nContrôler et développer du SI pour département Finance et Contrôle de gestion.\r\nContrôler la clôture mensuelle du groupe et automatisation des rapports.\r\nAnalyser les besoins du département FI&amp;CO et déploiements.', 'SAP FI, SAP CO'),
(835, 267, '30 Décembre 2020 - 30 Juillet 2023', 'Business Analyst', 'SAMSUNG Electronics', 'Elaborer le budget prévisionnel de l\'entreprise.\r\nContrôler la clôture du mois et l\'analyse des résultats réels par rapport aux prévisions et au budget.\r\nGérer le processus de reporting en garantissant la fiabilité, la cohérence, la transparence et le respect des délais. (PL, Net Sales, COP)\r\nSuivre l\'impact financier et l\'avancement des plans d\'actions des projets.\r\nGestion des projets (migration de system SAP ECC vers SAP S4/HANA &amp; création de system Hybris pour les ventes en ligne).\r\nGérer les tâches/projets ad-hoc assignés par le manager.\r\nContrôler les remises promotionnelles « Sales Deduction ».', 'SAP ECC, SAP S4/HANA, Hybris'),
(836, 267, '27 Janvier - 29 Décembre 2020', 'Account Manager', 'FINASHORE - Groupe BANK OF AFRICA', 'Apporter des solutions commerciales ainsi que techniques.\r\nEdition des rapports mensuels et quotidiens/', ''),
(837, 267, '24 Juin - 10 Octobre 2019', 'Financial Analyst', 'AFRICAN HOTEL MANAGEMENT CASABLANCA', 'Comptabilité bancaire sur Sage 1000\r\nPréparation et soumission des déclarations de TVA', 'Sage 1000'),
(845, 269, 'Depuis Janvier 2011', 'Ingénieur Système de production Senior N3 / Référent technique', 'Atos (Clients: SSC, PWC, Airliquide, SEPHORA)', '- Administrer Windows serveur 2003, 2008, 2012, 2016, 2019. Linux (selon périmètre),\r\n- Exploitation et optimisation des environnements Azure, M365, ADConnect,\r\n- Administrer les plateformes VMware et Citrix, gestion des resources et calculs de performance\r\n- Piloter et faire évoluer les indicateurs de suivi (OLAs/SLAs, KPI)\r\n- Gestion des incidents de production N3: MCO et réalisation des Changes.\r\n- Gestion des changements complexes (plan de changement, rollback, risques, CAB).\r\n- Automatisation des tâches récurrentes (PowerShell, Bash, Python).\r\n- Gérer des solutions de sauvegarde et Restauration: NetBackup, Veeam.\r\n- Administrer l\'outil SCCM 2010 (Télé-distribution et packaging).\r\n- Exploiter les rapports gérés par l\'outil Qualys pour la gestion des Vulnérabilités.\r\n- Traiter les vulnérabilités SSL/TLS.\r\n- Mise en place de bout en bout d\'une infrastructure Physiques et virtuelles (Des serveurs physiques, des châssis, des ESXis version 8, des bullions S4S2 en version 6.5, des baies de stockage, des modules shelfs, Datadomain, Netbackup, VSPHERE, P2V, V2V, Monitoring...).\r\n- Gérer les patchs par WSUS et SCCM.\r\n- Planifier, prioriser, coordonner et communiquer les demandes d\'évolution entre les différents Groupes de Support.\r\n- Mettre en place un calendrier de patching mensuel pour le Client.\r\n- Réaliser des Reportings Prod, Tableaux de Bord et Risque lettre de Sécurité.\r\n- Diagnostic de la Root cause des incidents récurrents (fichiers log, fichiers param, eventViewer) en participant à l\'amélioration continue et proposition des actions correctives\r\n- Garant de la disponibilité et conduite industrielle des applications du SI interne des clients.\r\n- Participer à la rédaction de procédures d\'exploitation.\r\n- Transfert des compétences aux analystes d\'exploitation.\r\n- Chargé des aspects de sécurité, MCO, Capacité Planning, Clients Atos\r\n- Etablissement des Dashboard, analyses, et suivi des actions avec tous les corps de métiers, dans le cadre du maintien en condition opérationnel, court, Moyen et long terme.\r\n- Participé fonctionnellement sur des Projets de migration et d\'implémentation.\r\n- Réalisations: Mettre en place des Dashboard de suivi, Sécurité Antivirus, MCO, Capacités Serveurs et Métrologies.', 'Windows Server 2003/2008/2012/2016/2019/2022, Linux, Ubuntu, Redhat, Azure, M365, ADConnect, VMware, Citrix, PowerShell, Bash, Python, NetBackup, Veeam, SCCM 2010, Qualys, SSL/TLS, ESXi, Bullion S4S2, Datadomain, vSphere, P2V, V2V, WSUS, AWS, SCOM, Nagios, Apache, Tomcat, IIS, NetApp, Dell EMC'),
(846, 269, 'Novembre 2013 - Août 2018', 'Ingénieur de production N3', 'VeTech VEOLIA-DALKIA', '- Suivi de l\'état d\'avancement sur le transfert des compétences des projets.\r\n- Garant de l\'infrastructure sur le périmètre dédié (Support, Supervision, Exploitation, Administration Technique et Réseau) et le suivi au quotidien de la production et la bonne tenue des engagements fournisseurs (SLA).\r\n- Etudier et identifier les risques du projet.\r\n- Transition: Démarrage du projet pour l\'équipe de Supervision et d\'exploitation, autant que Référent technique au sein des locaux VETECH - VEOLIA.\r\n- Suivi des actions de la transition sur tout le périmètre.\r\n- Validation des différentes consignes et procédures existantes en transition.\r\n- Participation aux différents comités techniques.\r\n- Suivi des incidents techniques et la coordination des escalades entre les différents intervenants.\r\n- Suivi de l\'amélioration continue et les indicateurs de qualité « KPI » Déjà définie.\r\n- Garant du bon fonctionnement des processus de production entre les parties (gestion des incidents, gestion des problèmes, gestion des changements)\r\n- Gestion de l\'équipe, notamment les Plannings, les formations et gestion de carrière.\r\n- Management et Coordination de deux équipes de 14 collaborateurs (Casa et Rabat) dans le cadre du PCA &amp; PRA (plan de continuité et reprise d\'activité)\r\n- Validation des différentes consignes et procédures reçues par le Client\r\n- Planification des ressources en veillant à leur montée en compétence et en fonction du besoin client et des compétences disponibles\r\n- Consolidation des consignes et procédures\r\n- Référent technique sur la partie Infrastructure (Serveur, VMware)\r\n- Identifie la cause source et Propose des correctifs\r\n- Formation technique sur la production Client et Clients finaux\r\n- Analyse des dysfonctionnements et la mise en place des plans d\'actions\r\n- Participation aux points quotidiens (Daily Report)\r\n- Analyse et plan d\'action des écarts de production\r\n- Participation aux réunions RCA/MIR', 'Windows Server 2003 R2/2008 R2/2012 R2/2016 R2, Linux Redhat 6.x, PowerShell, PowerCLI, Batch, Shell, Nagios, Adagios, Citrix Director, SCOM, HPSIM, HPOpenView, Citrix XenApp, Citrix XenServer, Citrix XenDesktop, VMware ESX, VMware ESXi, VMware vSphere 6.5, Hyper-V, TCP/IP, Citrix NetScaler, VirtualConnect, Firewall, LoadBalancing, NetBackup, Dell EMC, NetApp, Trend Micro, Kaspersky'),
(847, 269, 'Avril 2011 - Octobre 2013', 'Ingénieur N2 shift 2*8', 'GEFCO, Canal+, Laredoute, Celio, VIVARTE, LDS, Rexel', '- Assurer la gestion et l\'administration N2 sur toute l\'infrastructure des Clients\r\n- Gestion des platesformes et Serveurs MS Active Directory, DNS, DHCP, cluster,\r\n- Gestion des Consoles Antivirus (McAfee, trendMicro, Kaspersky, et Symantec)\r\n- Gestion des platesformes Microsoft Exchange\r\n- Déploiement des correctifs Hardware/Software (Firmware, WSUS)\r\n- Gestion des environnements Citrix et VMWARE.\r\n- Gestion des sauvegardes et restaurations Mutualisée et dédier avec les outils Netbackup, EMC NetWorker.\r\n- Gestion des incidents, des problèmes, des changements, Mise en place de référentiels, Suivi des indicateurs, et respect des SLA.\r\n- Assurer les astreintes et les escalades Client.\r\n- Reporting, réunions et comptes rendus d\'intervention pour nos clients....\r\n- Création des comptes rendus de l\'activité\r\n- Déclencher ou organiser les interventions de maintenance et s\'assurer de leur conformité\r\n- Test et validation des consignes', 'VMware vSphere 6.5/6.0/5.x, Windows Server 2003 R2/2008 R2/2012 R2, Linux Redhat 6.x, Citrix XenServer, PowerShell, PowerCLI, Batch, Shell, Nagios, ASE, SCOM, Citrix Metaframe, VMware ESX, VMware ESXi, Hyper-V, Trend Micro, Kaspersky, Apache, Tomcat, IIS, NetBackup, EMC NetWorker, BESR, Active Directory, DNS, DHCP, McAfee, Symantec, WSUS'),
